/**
 * feezal-element-system-connection-status — the portal behaviour that lets it
 * live on a hidden view (e.g. the autogenerated "System" view). Its overlay is
 * position:fixed but would be killed by an ancestor `display:none`, so in the
 * viewer the element hoists itself to <body>; in the editor it stays put and
 * shows its placeholder.
 */
import {describe, it, expect, beforeEach, afterEach, vi} from 'vitest';
import '@feezal/feezal-element-system-connection-status';

function setup(overrides = {}) {
    const conn = new EventTarget();
    conn.connected = true;
    conn.sub = () => ({}); conn.unsubscribe = () => {}; conn.pub = () => {}; conn.subCount = () => 0;
    window.feezal = {isEditor: false, views: [], connection: conn, ...overrides};
    document.body.innerHTML = '';
}

beforeEach(() => { vi.useFakeTimers(); setup(); });
afterEach(() => { vi.useRealTimers(); document.body.innerHTML = ''; });

describe('feezal-element-system-connection-status — portal', () => {
    it('viewer: hoists itself to <body> so a display:none view can not hide the overlay', async () => {
        const container = document.createElement('div');   // stands in for a <feezal-view>
        document.body.appendChild(container);
        const el = document.createElement('feezal-element-system-connection-status');
        container.appendChild(el);
        await el.updateComplete;

        expect(el.parentNode).toBe(document.body);          // portaled out of the container
        expect(el.hasAttribute('viewer-inert')).toBe(true);
        expect(container.querySelector('feezal-element-system-connection-status')).toBeNull();
    });

    it('editor: stays in place (no portal) and shows the placeholder', async () => {
        setup({isEditor: true});
        const container = document.createElement('div');
        document.body.appendChild(container);
        const el = document.createElement('feezal-element-system-connection-status');
        container.appendChild(el);
        await el.updateComplete;

        expect(el.parentNode).toBe(container);              // not portaled in the editor
        expect(el.hasAttribute('viewer-inert')).toBe(false);
        expect(el.shadowRoot.querySelector('.editor-placeholder')).not.toBeNull();
    });
});
